class Counter {
    private int count = 0;

    // NOT thread-safe: count++ is 3 operations
    public void increment() { count++; }

    // Thread-safe
    public synchronized void incrementSafe() { count++; }
}
// Without sync: 1000 increments from 2 threads may give < 2000
// With sync: always gives exactly 2000
