public void processAndUpdate(Data data) {
    // Non-critical: can run concurrently
    Result result = heavyComputation(data);

    // Critical section: only this part needs protection
    synchronized(this) {
        sharedList.add(result);
    }
    // Rest runs concurrently
    logResult(result);
}
