Object lock1 = new Object();
Object lock2 = new Object();

// Thread A: acquires lock1, then waits for lock2
new Thread(() -> {
    synchronized(lock1) {
        Thread.sleep(100);
        synchronized(lock2) { /* work */ } // waits here
    }
}).start();

// Thread B: acquires lock2, then waits for lock1
new Thread(() -> {
    synchronized(lock2) {
        Thread.sleep(100);
        synchronized(lock1) { /* work */ } // waits here
    }
}).start();
// Both threads block forever
```

