AtomicInteger counter = new AtomicInteger(0);

// Thread-safe increment — no synchronized needed
counter.incrementAndGet();  // returns new value
counter.getAndIncrement();  // returns old value
counter.addAndGet(5);       // add 5 atomically

// CAS: only sets if current value matches expected
counter.compareAndSet(10, 20); // if 10, set to 20
